// Parse interaction log (assuming JSON format)
const data = JSON.parse(items[0].binary.data);
const filename = $('Watch CRM Folder').first().json.path.split('/').pop().replace('.json', '');

return {
  json: {
    name: `CRM: ${data.customer_name || 'Unknown'} - ${data.interaction_type || 'Contact'}`,
    content: `Customer: ${data.customer_name}\nCompany: ${data.company || 'N/A'}\nType: ${data.interaction_type}\nNotes: ${data.notes || ''}\nProducts Discussed: ${(data.products || []).join(', ')}\nNext Steps: ${data.next_steps || 'None'}`,
    source: 'crm',
    source_description: `CRM interaction log: ${filename}`,
    reference_time: data.timestamp || new Date().toISOString()
  }
};

// Log success
const result = items[0].json;
console.log(`Stored CRM interaction: ${result.episode_uuid}`);
return items;
